BEGIN
 IF NOT pg_try_advisory_xact_lock(72461,2) THEN RAISE EXCEPTION 'INTERNAL_VERSION_IO_PRESENT' USING ERRCODE='55000'; END IF;
 IF EXISTS(SELECT 1 FROM pg_stat_activity WHERE datname=current_database() AND usename=replace(current_user,'qf_owner_','qf_app_') AND pid<>pg_backend_pid()) THEN RAISE EXCEPTION 'INTERNAL_VERSION_WRITERS_PRESENT' USING ERRCODE='55000'; END IF;
 SELECT jsonb_agg(jsonb_build_object('table_name',c.relname,'column_name',a.attname,'column_type',format_type(a.atttypid,a.atttypmod),'required',a.attnotnull,'default_expression',pg_get_expr(d.adbin,d.adrelid)) ORDER BY c.relname,a.attnum) INTO actual FROM pg_attribute a JOIN pg_class c ON c.oid=a.attrelid JOIN pg_namespace n ON n.oid=c.relnamespace LEFT JOIN pg_attrdef d ON d.adrelid=c.oid AND d.adnum=a.attnum WHERE n.nspname='qf' AND c.relname IN ('product_draft','draft_revision','draft_application') AND a.attnum>0 AND NOT a.attisdropped;
 IF actual IS DISTINCT FROM $columns$[{"table_name":"draft_application","column_name":"id","column_type":"uuid","required":true,"default_expression":null},{"table_name":"draft_application","column_name":"product_id","column_type":"character varying(80)","required":true,"default_expression":null},{"table_name":"draft_application","column_name":"idempotency_key","column_type":"uuid","required":true,"default_expression":null},{"table_name":"draft_application","column_name":"fingerprint","column_type":"character(64)","required":true,"default_expression":null},{"table_name":"draft_application","column_name":"source_import_id","column_type":"uuid","required":true,"default_expression":null},{"table_name":"draft_application","column_name":"source_validation_id","column_type":"uuid","required":true,"default_expression":null},{"table_name":"draft_application","column_name":"expected_validation_state_revision","column_type":"integer","required":true,"default_expression":null},{"table_name":"draft_application","column_name":"expected_candidate_sha256","column_type":"character(64)","required":true,"default_expression":null},{"table_name":"draft_application","column_name":"target_kind","column_type":"text","required":true,"default_expression":null},{"table_name":"draft_application","column_name":"draft_id","column_type":"uuid","required":true,"default_expression":null},{"table_name":"draft_application","column_name":"revision","column_type":"integer","required":true,"default_expression":null},{"table_name":"draft_application","column_name":"created_by","column_type":"uuid","required":true,"default_expression":null},{"table_name":"draft_application","column_name":"created_at","column_type":"timestamp with time zone","required":true,"default_expression":null},{"table_name":"draft_application","column_name":"expected_draft_revision","column_type":"integer","required":false,"default_expression":null},{"table_name":"draft_application","column_name":"expected_base_content_sha256","colu