 SELECT jsonb_agg(jsonb_build_object('table_name',c.relname,'name',k.conname,'definition',pg_get_constraintdef(k.oid),'kind',k.contype) ORDER BY c.relname,k.conname) INTO actual FROM pg_constraint k JOIN pg_class c ON c.oid=k.conrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='qf' AND (c.relname IN ('product_draft','draft_revision','draft_application') OR(c.relname='quizpack_validation' AND k.conname='validation_product_import_id') OR(c.relname='audit_event' AND k.conname='audit_target')) AND k.convalidated AND k.conenforced;
 IF actual IS DISTINCT FROM $constraints$[{"table_name":"audit_event","name":"audit_target","definition":"CHECK ((((target_kind IS NULL) AND (target_id IS NULL) AND (target_revision IS NULL) AND (action = ANY (ARRAY['bootstrap'::qf.audit_action, 'operator_disabled'::qf.audit_action, 'preauth_created'::qf.audit_action, 'login_succeeded'::qf.audit_action, 'login_failed'::qf.audit_action, 'logout'::qf.audit_action, 'session_revoked'::qf.audit_action]))) OR ((target_kind IS NOT NULL) AND (target_id IS NOT NULL) AND (target_revision IS NOT NULL) AND (target_revision >= 1) AND (actor_id IS NOT NULL) AND (session_id IS NOT NULL) AND (outcome = 'success'::qf.audit_outcome) AND (reason_code IS NULL) AND ((((target_kind)::text = 'product'::text) AND ((target_id)::text ~ '^[a-z][a-z0-9]*(-[a-z0-9]+)*$'::text) AND (action = ANY (ARRAY['product_created'::qf.audit_action, 'product_updated'::qf.audit_action, 'product_archived'::qf.audit_action, 'product_restored'::qf.audit_action]))) OR (((target_kind)::text = 'category'::text) AND ((target_id)::text ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'::text) AND (action = ANY (ARRAY['category_created'::qf.audit_action, 'category_updated'::qf.audit_action, 'category_archived'::qf.audit_action, 'category_restored'::qf.audit_action]))) OR (((target_kind)::text = 'tag'::text) AND ((target_id)::text ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'::text) AND (action = ANY (ARRAY['tag_created'::qf.audit_action, 'tag_updated'::qf.audit_action, 'tag_archived'::qf.audit_action, 'tag_restored'::qf.audit_action]))) OR (((target_kind)::text = 'validation'::text) AND ((target_id)::text ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'::text) AND (action = ANY (ARRAY['validation_started'::qf.audit_action, 'validation_evidenced'::qf.audit_action, 'validation_rejected'::qf.audit_action, 'validation_interrupted'::qf.audit_action, 'validation_completed'::qf.audit_action, 'validation_recovered'::qf.audit_action, 'validation_retried'::qf.audit_action, 'validation_file_stop_acknowledged'::qf.audit_action]))) OR (((target_kind)::text = 'draft'::text) AND ((target_id)::text ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'::text) AND ((target_revision >= 1) AND (target_revision <= 100)) AND (action = 'draft_applied'::qf.audit_action)) OR (((target_kind)::text = 'import'::text) AND ((target_id)::text ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'::text) AND (action = ANY (ARRAY['import_intent_created'::qf.audit_action, 'import_receive_started'::qf.audit_action, 'import_receive_completed'::qf.audit_action, 'import_receive_failed'::qf.audit_action, 'import_receive_recovered'::qf.audit_action])))))))","kind":"c"},{"table_name":"draft_application","name":"draft_application_closure","definition":"TRIGGER DEFERRABLE INITIALLY DEFERRED","kind":"t"},{"table_name":"draft_application","name":"draft_application_created_at_not_null","definition":"NOT NULL created_at","kind":"n"},{"table_name":"draft_application","name":"draft_application_created_by_fkey","definition":"FOREIGN KEY (created_by) REFERENCES qf.operator(id) ON DELETE RESTRICT","kind":"f"},{"table_name":"draft_application","name":"draft_application_created_by_not_null","definition":"NOT NULL created_by","kind":"n"},{"table_name":"draft_application","name":"draft_application_draft_id_not_null","definition":"NOT NULL draft_id","kind":"n"},{"table_name":"draft_application","name":"draft_application_expected_candidate_sha256_check","definition":"CHECK ((expected_candidate_sha256 ~ '^[a-f0-9]{64}$'::text))","kind":"c"},{"table_name":"draft_application","name":"draft_application_expected_candidate_sha256_not_null","definition":"NOT NULL expected_candidate_sha256","kind":"n"},{"table_name":"draft_application","name":"draft_application_expected_validation_state_revision_check","definition":"CHECK (((expected_validation_state_revision >= 1) AND (expected_validation_state_revision <= 214748