ision <= 99)) AND (revision = (expected_draft_revision + 1)) AND (expected_base_content_sha256 ~ '^[a-f0-9]{64}$'::text) AND (expected_base_asset_set_sha256 ~ '^[a-f0-9]{64}$'::text))) IS TRUE))","kind":"c"},{"table_name":"draft_application","name":"draft_application_parent_fk","definition":"FOREIGN KEY (product_id, draft_id, expected_draft_revision, expected_base_content_sha256, expected_base_asset_set_sha256) REFERENCES qf.draft_revision(product_id, draft_id, revision, canonical_content_sha256, asset_set_sha256) ON UPDATE RESTRICT DEFERRABLE INITIALLY DEFERRED","kind":"f"},{"table_name":"draft_application","name":"draft_application_pkey","definition":"PRIMARY KEY (id)","kind":"p"},{"table_name":"draft_application","name":"draft_application_product_id_draft_id_fkey","definition":"FOREIGN KEY (product_id, draft_id) REFERENCES qf.product_draft(product_id, id) ON UPDATE RESTRICT DEFERRABLE INITIALLY DEFERRED","kind":"f"},{"table_name":"draft_application","name":"draft_application_product_id_draft_id_revision_id_key","definition":"UNIQUE (product_id, draft_id, revision, id)","kind":"u"},{"table_name":"draft_application","name":"draft_application_product_id_draft_id_revision_id_source_im_key","definition":"UNIQUE (product_id, draft_id, revision, id, source_import_id, source_validation_id, expected_validation_state_revision, expected_candidate_sha256)","kind":"u"},{"table_name":"draft_application","name":"draft_application_product_id_draft_id_revision_key","definition":"UNIQUE (product_id, draft_id, revision)","kind":"u"},{"table_name":"draft_application","name":"draft_application_product_id_idempotency_key_key","definition":"UNIQUE (product_id, idempotency_key)","kind":"u"},{"table_name":"draft_application","name":"draft_application_product_id_not_null","definition":"NOT NULL product_id","kind":"n"},{"table_name":"draft_application","name":"draft_application_product_id_source_import_id_key","definition":"UNIQUE (product_id, source_import_id)","kind":"u"},{"table_name":"