ALTER TABLE qf.draft_revision ADD CONSTRAINT draft_revision_exact_target UNIQUE(product_id,draft_id,revision,canonical_content_sha256,asset_set_sha256,canonical_manifest_sha256);

-- The protocol has ASCII field names and bounded integer numeric fields. Strings are never normalized.
CREATE FUNCTION qf.internal_canonical(v jsonb) RETURNS text LANGUAGE plpgsql IMMUTABLE STRICT SET search_path=pg_catalog AS $$
DECLARE result text;
BEGIN
 CASE jsonb_typeof(v)
 WHEN 'object' THEN SELECT '{'||coalesce(string_agg(to_jsonb(key)::text||':'||qf.internal_canonical(value),',' ORDER BY key COLLATE "C"),'')||'}' INTO result FROM jsonb_each(v);
 WHEN 'array' THEN SELECT '['||coalesce(string_agg(qf.internal_canonical(value),',' ORDER BY ordinal),'')||']' INTO result FROM jsonb_array_elements(v) WITH ORDINALITY AS a(value,ordinal);
 ELSE result:=v::text;
 END CASE;
 RETURN result;
END $$;
CREATE FUNCTION qf.internal_registry_identity(v jsonb, expected_kind text) RETURNS boolean LANGUAGE sql IMMUTABLE STRICT SET search_path=pg_catalog AS $$
 SELECT (v=jsonb_build_object('kind',expected_kind,'id',v->'id','version',v->'version','entrySha256',v->'entrySha256')
 AND length(v->>'id') BETWEEN 1 AND 80 AND v->>'id' ~ '^[a-z][a-z0-9]*(-[a-z0-9]+)*$'
 AND length(v->>'version') BETWEEN 1 AND 32 AND v->>'version' ~ '^(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)$'
 AND v->>'entrySha256' ~ '^[a-f0-9]{64}$') IS TRUE
$$;

CREATE TABLE qf.draft_review (
 id uuid PRIMARY KEY,
 product_id varchar(80) NOT NULL,
 draft_id uuid NOT NULL,
 revision integer NOT NULL CHECK(revision BETWEEN 1 AND 100),
 canonical_content_sha256 char(64) NOT NULL,
 asset_set_sha256 char(64) NOT NULL,
 canonical_manifest_sha256 char(64) NOT NULL,
 source_import_id uuid NOT NULL,
 source_validation_id uuid NOT NULL,
 source_validation_state_revision integer NOT NULL CHECK(source_validation_state_revision BETWEEN 1 AND 2147483647),
 purpose text NOT NULL CHECK(purpose='internal-test'),
 idempotency_key uuid NOT NULL,
 binding_text text NOT NULL CHECK(octet_length(binding_text) BETWEEN 2 AND 4096),
 fingerprint char(64) NOT NULL CHECK(fingerprint ~ '^[a-f0-9]{64}$'),
 facts_text text NOT NULL CHECK(octet_length(facts_text) BETWEEN 2 AND 8192),
 review_sha256 char(64) NOT NULL CHECK(review_sha256 ~ '^[a-f0-9]{64}$'),
 recorded_by uuid NOT NULL REFERENCES qf.operator(id) ON DELETE RESTRICT,
 recorded_at timestamptz NOT NULL CHECK(date_trunc('milliseconds',recorded_at)=recorded_at),
 CONSTRAINT draft_review_operation UNIQUE(product_id,idempotency_key),
 CONSTRAINT draft_review_target UNIQUE(product_id,draft_id,revision),
 CONSTRAINT draft_review_exact UNIQUE(product_id,id,draft_id,revision,canonical_content_sha256,asset_set_sha256,canonical_manifest_sha256,review_sha256,purpose),
 CONSTRAINT draft_review_revision FOREIGN KEY(product_id,draft_id,revision,canonical_content_sha256,asset_set_sha256,canonical_manifest_sha256) REFERENCES qf.draft_revision(product_id,draft_id,revision,canonical_content_sha256,asset_set_sha256,canonical_manifest_sha256) ON UPDATE RESTRICT ON DELETE RESTRICT
);
CREATE FUNCTION qf.internal_review_valid(r qf.draft_review) RETURNS boolean LANGUAGE plpgsql IMMUTABLE STRICT SET search_path=pg_catalog AS $$
DECLARE b jsonb; f jsonb; t jsonb; a jsonb;
BEGIN
 b:=r.binding_text::jsonb; f:=r.facts_text::jsonb; a:=f->'approval';
 t:=jsonb_build_object('draftId',r.draft_id,'revision',r.revision,'canonicalContentSha256',r.canonical_content_sha256::text,'assetSetSha256',r.asset_set_sha256::text,'canonicalManifestSha256',r.canonical_manifest_sha256::text);
 RETURN (r.binding_text=qf.internal_canonical(b) AND r.fingerprint::text=qf.sha256_utf8(r.binding_text)
 AND b=jsonb_build_object('schemaVersion','quizforge.review-record.v1','productId',r.product_id,'idempotencyKey',r.idempotency_key,'target',t,'baseline',b->'baseline')
 AND qf.internal_registry_identity(b->'baseline','baseline')
 AND r.facts_text=qf.internal_canonical(f) AND r.review_sha256::text=qf.sha256_utf8(r.facts_text)
 AND f=jsonb_build_object('schemaVersion','quizforge.internal-review-facts.v1','productId',r.product_id,'target',t,'baseline',b->'baseline','purpose',r.purpose,'approval',a)
 AND ((a->>'kind'='author-baseline' AND a=jsonb_build_object('kind','author-baseline','approvedOn',a->'approvedOn','sourceRecordId',a->'sourceRecordId','evidenceSha256',a->'evidenceSha256','scope','internal-test-content-and-visual-baseline') AND a->>'approvedOn' ~ '^\d{4}-\d{2}-\d{2}$' AND a->>'sourceRecordId' ~ '^[a-z][a-z0-9]*(-[a-z0-9]+)*$')
 OR (a->>'kind'='synthetic-test' AND a=jsonb_build_object('kind','synthetic-test','fixtureId',a->'fixtureId','evidenceSha256',a->'evidenceSha256','scope','test-evidence-no-author-approval') AND a->>'fixtureId' ~ '^[a-z][a-z0-9]*(-[a-z0-9]+)*$'))
 AND a->>'evidenceSha256' ~ '^[a-f0-9]{64}$') IS TRUE;
EXCEPTION WHEN OTHERS THEN RETURN false;
END $$;
ALTER TABLE qf.draft_review ADD CONSTRAINT draft_review_text_exact CHECK(qf.internal_review_valid(draft_review) IS TRUE);

CREATE TABLE qf.product_version (
 id uuid PRIMARY KEY,
 product_id varchar(80) NOT NULL,
 slot integer NOT NULL CHECK(slot BETWEEN 1 AND 100),
 draft_id uuid NOT NULL,
 revision integer NOT NULL CHECK(revision BETWEEN 1 AND 100),
 canonical_content_sha256 char(64) NOT NULL,
 asset_set_sha256 char(64) NOT NULL,
 canonical_manifest_sha256 char(64) NOT NULL,
 review_id uuid NOT NULL,
 review_sha256 char(64) NOT NULL,
 purpose text NOT NULL CHECK(purpose='internal-test'),
 publication_approved boolean NOT NULL CHECK(publication_approved=false),
 idempotency_key uuid NOT NULL,
 binding_text text NOT NULL CHECK(octet_length(binding_text) BETWEEN 2 AND 4096),
 fingerprint char(64) NOT NULL CHECK(fingerprint ~ '^[a-f0-9]{64}$'),
 snapshot_text text NOT NULL CHECK(octet_length(snapshot_text) BETWEEN 2 AND 32768),
 snapshot_sha256 char(64) NOT NULL CHECK(snapshot_sha256 ~ '^[a-f0-9]{64}$'),
 created_by uuid NOT NULL REFERENCES qf.operator(id) ON DELETE RESTRICT,
 created_at timestamptz NOT NULL CHECK(date_trunc('milliseconds',created_at)=created_at),
 CONSTRAINT product_version_operation UNIQUE(product_id,idempotency_key),
 CONSTRAINT product_version_capacity UNIQUE(product_id,slot),
 CONSTRAINT product_version_snapshot UNIQUE(product_id,snapshot_sha256),
 CONSTRAINT product_version_review FOREIGN KEY(product_id,review_id,draft_id,revision,canonical_content_sha256,asset_set_sha256,canonical_manifest_sha256,review_sha256,purpose) REFERENCES qf.draft_review(product_id,id,draft_id,revision,canonical_content_sha256,asset_set_sha256,canonical_manifest_sha256,review_sha256,purpose) ON UPDATE RESTRICT ON DELETE RESTRICT
);
CREATE FUNCTION qf.internal_version_valid(r qf.product_version) RETURNS boolean LANGUAGE plpgsql IMMUTABLE STRICT SET search_path=pg_catalog AS $$
DECLARE b jsonb; s jsonb; t jsonb;
BEGIN
 b:=r.binding_text::jsonb; s:=r.snapshot_text::jsonb;
 t:=jsonb_build_object('draftId',r.draft_id,'revision',r.revision,'canonicalContentSha256',r.canonical_content_sha256::text,'assetSetSha256',r.asset_set_sha256::text,'canonicalManifestSha256',r.canonical_manifest_sha256::text);
 RETURN (r.binding_text=qf.internal_canonical(b) AND r.fingerprint::text=qf.sha256_utf8(r.binding_text)
 AND b=jsonb_build_object('schemaVersion','quizforge.internal-version-seal.v1','productId',r.product_id,'idempotencyKey',r.idempotency_key,'target',t,'reviewId',r.review_id,'reviewSha256',r.review_sha256::text,'renderer',b->'renderer','engine',b->'engine')
 AND qf.internal_registry_identity(b->'renderer','renderer') AND qf.internal_registry_identity(b->'engine','engine')
 AND r.snapshot_text=qf.internal_canonical(s) AND r.snapshot_sha256::text=qf.sha256_utf8(r.snapshot_text)
 AND s=jsonb_build_object('schemaVersion','quizforge.internal-version-snapshot.v1','productId',r.product_id,'target',t,'reviewId',r.review_id,'reviewSha256',r.review_sha256::text,'baseline',s->'baseline','purpose',r.purpose,'publicationApproved',r.publication_approved,'contentSchemaVersion',s->'contentSchemaVersion','contentKind',s->'contentKind','packId',s->'packId','packVersion',s->'packVersion','versions',s->'versions','logicHash',s->'logicHash','renderer',b->'renderer','rendererCapability','studio-internal-preview','components',s->'components','engine',b->'engine','font',s->'font','validation',s->'validation')
 AND qf.internal_registry_identity(s->'baseline','baseline') AND s->>'logicHash' ~ '^[a-f0-9]{64}$'
 AND s->>'contentSchemaVersion'='quizpack-content.v2' AND s->>'contentKind' IN ('synthetic','authored')
 AND s->'versions'->>'componentVersion'='2.0.0' AND s->'versions'->'engine'->>'id'=b->'engine'->>'id' AND s->'versions'->'engine'->>'version'=b->'engine'->>'version') IS TRUE;
EXCEPTION WHEN OTHERS THEN RETURN false;
END $$;
ALTER TABLE qf.product_version ADD CONSTRAINT product_version_text_exact CHECK(qf.internal_version_valid(product_version) IS TRUE);

CREATE FUNCTION qf.protect_internal_reference() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$
DECLARE r qf.draft_revision; v qf.quizpack_validation; review qf.draft_review; s jsonb; head integer; archived timestamptz;
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'IMMUTABLE_INTERNAL_REFERENCE' USING ERRCODE='23514'; END IF;
 IF NOT pg_try_advisory_xact_lock_shared(72461,2) THEN RAISE EXCEPTION 'INTERNAL_REFERENCE_MAINTENANCE_BUSY' USING ERRCODE='55P03'; END IF;
 SELECT archived_at INTO archived FROM qf.product WHERE id=NEW.product_id FOR UPDATE;
 IF NOT FOUND OR archived IS NOT NULL THEN RAISE EXCEPTION 'INTERNAL_REFERENCE_PRODUCT_INACTIVE' USING ERRCODE='23514'; END IF;
 SELECT current_revision INTO head FROM qf.product_draft WHERE product_id=NEW.product_id AND id=NEW.draft_id;
 IF head IS DISTINCT FROM NEW.revision THEN RAISE EXCEPTION 'INTERNAL_REFERENCE_HEAD_CHANGED' USING ERRCODE='23514'; END IF;
 SELECT * INTO r FROM qf.draft_revision WHERE product_id=NEW.product_id AND draft_id=NEW.draft_id AND revision=NEW.revision;
 IF NOT FOUND THEN RAISE EXCEPTION 'INTERNAL_REFERENCE_SOURCE_MISSING' USING ERRCODE='23514'; END IF;
 IF TG_TABLE_NAME='draft_review' THEN
  IF (NEW.source_import_id,NEW.source_validation_id,NEW.source_validation_state_revision) IS DISTINCT FROM (r.source_import_id,r.source_validation_id,r.source_validation_state_revision) THEN RAISE EXCEPTION 'INTERNAL_REVIEW_SOURCE_MISMATCH' USING ERRCODE='23514'; END IF;
 ELSE
  SELECT * INTO review FROM qf.draft_review WHERE product_id=NEW.product_id AND id=NEW.review_id;
  SELECT * INTO v FROM qf.quizpack_validation WHERE product_id=r.product_id AND import_id=r.source_import_id AND id=r.source_validation_id;
  s:=NEW.snapshot_text::jsonb;
  IF review.id IS NULL OR v.id IS NULL OR s->'baseline' IS DISTINCT FROM review.facts_text::jsonb->'baseline'
   OR (s->>'packId',s->>'packVersion',s->>'contentSchemaVersion',s->>'contentKind') IS DISTINCT FROM (r.pack_id::text,r.pack_version::text,r.content_schema_version::text,r.content_kind::text)
   OR s->'versions' IS DISTINCT FROM jsonb_build_object('contentVersion',r.content_version,'visualVersion',r.visual_version,'reportVersion',r.report_version,'resourceVersion',r.resource_version,'componentVersion',r.component_version,'engine',jsonb_build_object('id',r.engine_id,'version',r.engine_version))
   OR s->'validation' IS DISTINCT FROM jsonb_build_object('sourceImportId',r.source_import_id,'sourceValidationId',r.source_validation_id,'sourceValidationStateRevision',r.source_validation_state_revision,'archiveSha256',v.archive_sha256::text,'candidateSha256',r.candidate_sha256::text,'identitySha256',v.identity_sha256::text,'validatorBundleSha256',v.identity_text::jsonb->>'validatorBundleSha256','archivePolicyVersion',v.archive_policy_version,'archivePolicySha256',v.archive_policy_sha256::text,'evidenceSha256',v.evidence_sha256::text)
  THEN RAISE EXCEPTION 'INTERNAL_VERSION_SOURCE_MISMATCH' USING ERRCODE='23514'; END IF;
 END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER draft_review_source BEFORE INSERT OR UPDATE ON qf.draft_review FOR EACH ROW EXECUTE FUNCTION qf.protect_internal_reference();
CREATE TRIGGER product_version_source BEFORE INSERT OR UPDATE ON qf.product_version FOR EACH ROW EXECUTE FUNCTION qf.protect_internal_reference();

