ALTER TYPE qf.audit_action ADD VALUE 'draft_baseline_recorded';
ALTER TYPE qf.audit_action ADD VALUE 'internal_version_sealed';
ALTER TABLE qf.audit_event DROP CONSTRAINT audit_target;
ALTER TABLE qf.audit_event ADD CONSTRAINT audit_target CHECK ((((((target_kind IS NULL) AND (target_id IS NULL) AND (target_revision IS NULL) AND (action = ANY (ARRAY['bootstrap'::qf.audit_action, 'operator_disabled'::qf.audit_action, 'preauth_created'::qf.audit_action, 'login_succeeded'::qf.audit_action, 'login_failed'::qf.audit_action, 'logout'::qf.audit_action, 'session_revoked'::qf.audit_action]))) OR ((target_kind IS NOT NULL) AND (target_id IS NOT NULL) AND (target_revision IS NOT NULL) AND (target_revision >= 1) AND (actor_id IS NOT NULL) AND (session_id IS NOT NULL) AND (outcome = 'success'::qf.audit_outcome) AND (reason_code IS NULL) AND ((((target_kind)::text = 'product'::text) AND ((target_id)::text ~ '^[a-z][a-z0-9]*(-[a-z0-9]+)*$'::text) AND (action = ANY (ARRAY['product_created'::qf.audit_action, 'product_updated'::qf.audit_action, 'product_archived'::qf.audit_action, 'product_restored'::qf.audit_action]))) OR (((target_kind)::text = 'category'::text) AND ((target_id)::text ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'::text) AND (action = ANY (ARRAY['category_created'::qf.audit_action, 'category_updated'::qf.audit_action, 'category_archived'::qf.audit_action, 'category_restored'::qf.audit_action]))) OR (((target_kind)::text = 'tag'::text) AND ((target_id)::text ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'::text) AND (action = ANY (ARRAY['tag_created'::qf.audit_action, 'tag_updated'::qf.audit_action, 'tag_archived'::qf.audit_action, 'tag_restored'::qf.audit_action]))) OR (((target_kind)::text = 'validation'::text) AND ((target_id)::text ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'::text) AND (action = ANY (ARRAY['validation_started'::qf.audit_action, 'validation_evidenced'::qf.audit_action, 'validation_rejected'::qf.audit_action, 'validation_interrupted'::qf.audit_action, 'validation_completed'::qf.audit_action, 'validation_recovered'::qf.audit_action, 'validation_retried'::qf.audit_action, 'validation_file_stop_acknowledged'::qf.audit_action]))) OR (((target_kind)::text = 'draft'::text) AND ((target_id)::text ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'::text) AND ((target_revision >= 1) AND (target_revision <= 100)) AND (action = 'draft_applied'::qf.audit_action)) OR (((target_kind)::text = 'import'::text) AND ((target_id)::text ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'::text) AND (action = ANY (ARRAY['import_intent_created'::qf.audit_action, 'import_receive_started'::qf.audit_action, 'import_receive_completed'::qf.audit_action, 'import_receive_failed'::qf.audit_action, 'import_receive_recovered'::qf.audit_action]))))))) OR (
 actor_id IS NOT NULL AND session_id IS NOT NULL AND target_kind IS NOT NULL AND target_revision IS NOT NULL AND outcome='success' AND reason_code IS NULL
 AND target_id IS NOT NULL AND target_id ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
 AND target_revision BETWEEN 1 AND 100 AND ((target_kind='review' AND action::text='draft_baseline_recorded') OR (target_kind='version' AND action::text='internal_version_sealed')))) IS TRUE);
REVOKE ALL ON qf.draft_review,qf.product_version FROM PUBLIC;
REVOKE ALL ON FUNCTION qf.internal_canonical(jsonb),qf.internal_registry_identity(jsonb,text),qf.internal_review_valid(qf.draft_review),qf.internal_version_valid(qf.product_version),qf.protect_internal_reference() FROM PUBLIC;
